param([Parameter(Mandatory)][string]$InputPath)
$trials=@(Get-Content $InputPath|ForEach-Object{$_|ConvertFrom-Json}|Where-Object trial)
[ordered]@{trials=$trials.Count;launchResponsiveMs=[ordered]@{min=($trials.launchResponsiveMs|Measure-Object -Minimum).Minimum;mean=[math]::Round(($trials.launchResponsiveMs|Measure-Object -Average).Average,2);max=($trials.launchResponsiveMs|Measure-Object -Maximum).Maximum};privateBytes=[ordered]@{min=($trials.privateBytes|Measure-Object -Minimum).Minimum;mean=[math]::Round(($trials.privateBytes|Measure-Object -Average).Average,0);max=($trials.privateBytes|Measure-Object -Maximum).Maximum};idleCpuPercentMean=[math]::Round(($trials.idleCpuPercent|Measure-Object -Average).Average,3);resizeSequenceMsMean=[math]::Round(($trials.resizeSequenceMs|Measure-Object -Average).Average,2);pipeConnectionsPassed=@($trials|Where-Object pipeServiceExitCode -EQ 0).Count}|ConvertTo-Json -Depth 5
